import{_ as n,C as r,o as i,c as o,a5 as s,E as l,j as a,a as d}from"./chunks/framework.BwlBv862.js";const b=JSON.parse('{"title":"Review changes by area","description":"","frontmatter":{"title":"Review changes by area","docId":"user.cloud.changes","translationKey":"user.cloud.changes","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"f875a22e66dd822d7ea1344188d8b7b087a23a777e072240a4a3c7c57969f995","translationRevision":"f875a22e66dd822d7ea1344188d8b7b087a23a777e072240a4a3c7c57969f995","order":20},"headers":[],"relativePath":"en/user/cloud/changes.md","filePath":"en/user/cloud/changes.md","lastUpdated":1794611623000}'),c={name:"en/user/cloud/changes.md"};function h(p,e,u,v,g,f){const t=r("DemoFrame");return i(),o("div",null,[e[0]||(e[0]=s('<h1 id="review-changes-by-area" tabindex="-1">Review changes by area <a class="header-anchor" href="#review-changes-by-area" aria-label="Permalink to &quot;Review changes by area {#review-changes-by-area}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Understand what a <strong>Changes</strong> panel compares before resetting, sending or adopting data. You need saved local content. Cloud operations additionally need a supported host, the relevant synchronization mode and a <a href="./account.html">signed-in account</a>. Panels with the same name do not all perform the same transport.</p><h2 id="review-events-and-actions-locally" tabindex="-1">Review Events and Actions locally <a class="header-anchor" href="#review-events-and-actions-locally" aria-label="Permalink to &quot;Review Events and Actions locally {#review-events-and-actions-locally}&quot;">​</a></h2><ol><li>Open <strong>Automations</strong>, select Events or Actions and open <strong>Changes</strong>.</li><li>Read the notice: this area compares current definitions with a reference retained on this device. The first loaded visit seeds that reference, so it can legitimately show no changes.</li><li>Select an added, modified or deleted record and inspect the before/after values.</li><li>Choose <strong>Mark as reviewed</strong> only when you want the current section to become the new local reference. This does not upload definitions or approve delegated execution.</li><li>Use <strong>Reset</strong> only when you intend to restore the reference. For a newly added record, reset removes it; for a modified/deleted record, it restores the retained definition. Save an export first if needed.</li></ol><p>The Events/Actions adapter has no Cloud collection for individual definitions in this version. A clean comparison is neither a Cloud backup nor evidence that another computer received your edits.</p><h2 id="review-variables-and-plugins-explicitly" tabindex="-1">Review Variables and Plugins explicitly <a class="header-anchor" href="#review-variables-and-plugins-explicitly" aria-label="Permalink to &quot;Review Variables and Plugins explicitly {#review-variables-and-plugins-explicitly}&quot;">​</a></h2><p>Variables have their own native reviewed sharing: save locally, fetch candidates, inspect the comparison and explicitly send, apply/adopt or withdraw. Secret or blocked values remain masked and cannot be sent through that path. Local save never uploads. See <a href="./../automations/variables.html">Variables</a>.</p><p>Plugin Changes uses its supported synchronization workspace for plugin selections and staged settings. Publication is section based rather than a separate send for every row. Settings show changed key names without exposing values; conflicts allow choosing the local or Cloud version, not arbitrary field merging. Read the section action and selected synchronization mode before publishing.</p><p>Cloud overlays use the <a href="./../overlays/">library/editor</a> create/revise flow. A shared overlay Changes adapter is not available in this base version.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Expected result, status and recovery <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Expected result, status and recovery {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Local automation comparison and capability-gated native sharing are available in their respective areas. Operations with remote side effects depend on the service; production acceptance is not implied. If a review becomes stale, refresh and compare again. If the outcome is unconfirmed, inspect status/journal information before creating another operation. Never treat a timeout as proof that nothing changed.</p>',12)),l(t,{scenario:"cloud",locale:"en",tour:"changes",title:"Demo: cloud"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[d("Operational details "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Operational details {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"Before v1 → v2 preparation/migration, back up local data and coordinate compatible versions on every device. In setup, prepare, check compatibility and preview; inspect selection, pending, conflict and v1-only counts rather than treating all as synchronized. Enforcing the write-epoch header is irreversible account-wide for v2 writes and can reject old devices. A barrier timeout is ambiguous; repeating a barrier advances it again. Refresh migration/epoch state and the current preview before any further action. Reading the epoch does not prove older writes completed.",-1)),e[3]||(e[3]=a("p",null,"Recovery depends on mode: Events/Actions Changes compares local references, so it does not send Cloud writes. For reviewed Variables/Plugins, reload stale comparisons and review current revisions, account and inventories. If plugins are missing, use the setup inventory review/repair and generate a new preview. For an uncertain retained intent, preserve its ID/evidence and inspect current history/state; technical recovery requires a fresh recovery review of frozen entries and Cloud revision. Resuming that reviewed intent does not itself send a remote write. Stop if state cannot be reconciled; do not create a replacement mutation to bypass uncertainty.",-1))])}const y=n(c,[["render",h]]);export{b as __pageData,y as default};
